builder.Services.AddAuthorization(o => {
    // deny by default: endpoints without an explicit policy still require authentication
    o.FallbackPolicy = new AuthorizationPolicyBuilder().RequireAuthenticatedUser().Build();
    o.AddPolicy("Pause", p => p.RequireRole("Pauser", "Admin"));   // role -> permission mapping
});

[Authorize(Policy = "Pause")]
public IActionResult Pause() => Ok();

